// n8n 2.x: Code node roda isolado (task runner) - apenas JS puro, sem env vars nem require.
// Le os dois endpoints, faz join por protocolo e emite 1 item por DIVERGENCIA.
// Divergencia-alvo: Splitters encerrou (status=encerrada) mas Elleven segue aberto (finalizado null).

function unwrap(resp) {
  if (Array.isArray(resp)) return resp;
  if (resp && Array.isArray(resp.data)) return resp.data;
  return [];
}

const elleven = unwrap($('GET Elleven').first().json);
const hist = unwrap($('GET History (Splitters)').first().json);
const limit = Number($('Config').item.json.limit) || 0;

const ellevenByProto = new Map();
for (const e of elleven) {
  if (e && e.protocolo != null) ellevenByProto.set(String(e.protocolo), e);
}

const divergencias = [];
for (const h of hist) {
  if (!h || h.protocolo == null) continue;
  const proto = String(h.protocolo);
  const e = ellevenByProto.get(proto);
  if (!e) continue;
  const fechadoNoSplitters = h.status === 'encerrada';
  const abertoNoElleven = !e.finalizado;
  if (fechadoNoSplitters && abertoNoElleven) {
    if (!h.assignmentId) continue;
    divergencias.push({
      json: {
        protocolo: proto,
        assignmentId: String(h.assignmentId),
        ultimaAcaoSplitters: h.ultimaAcaoEm,
        statusElleven: e.status,
        body: {
          assignmentId: String(h.assignmentId),
          incidentStatusId: '8',
          description: 'Encerramento automatico via reconciliacao n8n (Splitters x Voalle). Protocolo ' + proto + ' encerrado no Splitters em ' + (h.ultimaAcaoEm || 'N/D') + ' e ainda aberto no Voalle. Fonte da verdade: ultima acao = Splitters.',
          progress: '0',
          priority: '35',
          notificationTarget: '0',
          privateReport: 'true'
        }
      }
    });
  }
}

return limit > 0 ? divergencias.slice(0, limit) : divergencias;

// Classifica cada tentativa de fechamento: sucesso vs falha.
// Considera tanto erro HTTP/transporte quanto success:false no corpo da resposta.
const resultados = $input.all();
const origem = $('Reconciliar (diff)').all();
const sucessos = [];
const falhas = [];

resultados.forEach((item, i) => {
  const src = (origem[i] && origem[i].json) || {};
  const proto = src.protocolo || '(desconhecido)';
  const assignmentId = src.assignmentId || '';
  const j = item.json || {};

  if (j.error) {
    const msg = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    falhas.push({ protocolo: proto, assignmentId, motivo: 'Erro de transporte: ' + msg });
    return;
  }

  const status = j.statusCode;
  const body = (j.body !== undefined) ? j.body : j;
  const httpOk = (status === undefined) || (status >= 200 && status < 300);
  const logicOk = body && body.success === true;

  if (httpOk && logicOk) {
    sucessos.push({ protocolo: proto, assignmentId });
  } else {
    let motivo = 'HTTP ' + (status !== undefined ? status : '?');
    if (body && Array.isArray(body.messages) && body.messages.length) {
      motivo += ' - ' + body.messages.map(m => m.message).join('; ');
    } else if (body && body.message) {
      motivo += ' - ' + body.message;
    }
    falhas.push({ protocolo: proto, assignmentId, motivo });
  }
});

const temFalhas = falhas.length > 0;
const linhas = falhas.map(f => '<li>Protocolo <b>' + f.protocolo + '</b> (assignmentId ' + f.assignmentId + '): ' + f.motivo + '</li>').join('');
const assunto = '[Reconciliacao Massivas] ' + falhas.length + ' falha(s), ' + sucessos.length + ' sucesso(s)';
const corpoHtml = '<p>Reconciliacao Splitters x Voalle (Elleven) concluida.</p>'
  + '<p><b>Sucessos:</b> ' + sucessos.length + ' &nbsp; <b>Falhas:</b> ' + falhas.length + '</p>'
  + (temFalhas ? ('<p>Protocolos que <b>nao</b> puderam ser encerrados no Voalle:</p><ul>' + linhas + '</ul>') : '')
  + '<p>Protocolos encerrados com sucesso: ' + (sucessos.map(s => s.protocolo).join(', ') || '-') + '</p>';

return [{ json: { temFalhas, total: resultados.length, okCount: sucessos.length, falhaCount: falhas.length, sucessos, falhas, assunto, corpoHtml } }];
